sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  $scope.week     = 0;      // 0 = this week, 1 = next week
  $scope.dayYmd   = '';     // selected day, empty = no day filter
  $scope.typeVal  = '';
  $scope.selected = null;   // workspace shown in the detail panel
  $scope.selectedStrip = [];

  $scope.visibleDays = [];  // the five day tiles on show
  $scope.filtered    = [];  // everything matching the filters
  $scope.shown       = [];  // the slice actually rendered
  $scope.showAll     = false;

  var PAGE = 8;             // cards shown before "show all"

  // Everything below recomputes only when something actually
  // changes. Calling a function directly from ng-repeat returns a
  // new array every digest, which makes Angular re-render in a
  // loop and the count disagree with the grid.
  function recompute() {
    // Any filter change closes the detail panel — leaving it open
    // shows a space that may no longer be in the results.
    $scope.selected = null;
    $scope.selectedStrip = [];

    var offset = $scope.week * 5;

    $scope.visibleDays = $scope.data.days.slice(offset, offset + 5);

    // Index of the selected day within the full ten, or -1.
    var dayIdx = -1;
    if ($scope.dayYmd) {
      for (var i = 0; i < $scope.data.days.length; i++) {
        if ($scope.data.days[i].ymd === $scope.dayYmd) {
          dayIdx = i;
          break;
        }
      }
    }

    var out = [];
    var list = $scope.data.workspaces;

    for (var j = 0; j < list.length; j++) {
      var w = list[j];

      if ($scope.typeVal && w.typeVal !== $scope.typeVal) continue;
      if (dayIdx > -1 && w.days[dayIdx] !== 'free') continue;

      // Precompute what the card needs so the template reads
      // plain properties rather than calling functions.
      w.viewStrip = w.days.slice(offset, offset + 5);

      var free = 0;
      for (var k = 0; k < w.viewStrip.length; k++) {
        if (w.viewStrip[k] === 'free') free++;
      }
      w.viewFree = free;

      out.push(w);
    }

    $scope.filtered = out;
    $scope.shown = $scope.showAll ? out : out.slice(0, PAGE);
  }

  $scope.setWeek = function(n) {
    $scope.week = n;
    $scope.dayYmd = '';     // a day in the old week makes no sense now
    recompute();
  };

  $scope.toggleDay = function(ymd) {
    $scope.dayYmd = ($scope.dayYmd === ymd) ? '' : ymd;
    recompute();
  };

  // Must be a function: ng-repeat gives each pill its own child
  // scope, so an inline assignment would set it on the pill.
  $scope.setType = function(v) {
    $scope.typeVal = v;
    recompute();
  };

  $scope.clearFilters = function() {
    $scope.typeVal = '';
    $scope.dayYmd  = '';
    recompute();
  };

  $scope.toggleAll = function() {
    $scope.showAll = !$scope.showAll;
    $scope.shown = $scope.showAll
                 ? $scope.filtered
                 : $scope.filtered.slice(0, PAGE);
  };

  // --- detail panel ---

  $scope.open = function(w) {
    $scope.selected = w;

    // Ten day/state pairs, built once when the panel opens.
    var full = [];
    for (var i = 0; i < $scope.data.days.length; i++) {
      full.push({
        day:   $scope.data.days[i],
        state: w.days[i]
      });
    }
    $scope.selectedStrip = full;
  };

  $scope.close = function() {
    $scope.selected = null;
    $scope.selectedStrip = [];
  };

  recompute();
};

sp_widget.css:
.wrm-wk-head { display: flex; align-items: center; gap: 14px; margin-bottom: 14px; }
.wrm-wk-head h2 { margin: 0; font-size: 22px; color: var(--ink); }

.wrm-wk-toggle { margin-left: auto; display: flex; gap: 6px; }
.wrm-wk-toggle button {
  font-size: 12px; padding: 6px 14px; border: 1px solid var(--line);
  background: var(--surface); color: var(--ink-2);
  border-radius: var(--r-pill); cursor: pointer;
}
.wrm-wk-toggle button.on { background: var(--ink); border-color: var(--ink); color: var(--paper); }

.wrm-wk-bar { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; margin-bottom: 12px; }
.wrm-wk-day {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--r-soft); padding: 10px 8px; text-align: center; cursor: pointer;
}
.wrm-wk-day .lbl { display: block; font-size: 10px; letter-spacing: .07em; color: var(--ink-3); }
.wrm-wk-day .num { display: block; font-size: 20px; line-height: 1.3; color: var(--ink); }
.wrm-wk-day .sub { display: block; font-size: 10px; color: var(--ink-3); }
.wrm-wk-day.today { border-color: var(--ink-3); }
.wrm-wk-day.on { background: var(--clay); border-color: var(--clay); }
.wrm-wk-day.on .lbl, .wrm-wk-day.on .num, .wrm-wk-day.on .sub { color: var(--on-clay); }

.wrm-wk-pills { display: flex; gap: 7px; flex-wrap: wrap; margin-bottom: 8px; }
.wrm-wk-pills button {
  font-size: 12px; padding: 6px 14px; border: 1px solid var(--line);
  background: var(--surface); color: var(--ink-2);
  border-radius: var(--r-pill); cursor: pointer;
}
.wrm-wk-pills button.on { background: var(--ink); border-color: var(--ink); color: var(--paper); }

.wrm-wk-count { font-size: 12px; color: var(--ink-3); margin: 12px 0; }
.wrm-wk-count .clear {
  background: none; border: 0; color: var(--clay);
  font-size: 12px; cursor: pointer; padding: 0 0 0 10px;
}

.wrm-wk-detail {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  padding: 18px 20px;
  margin: 14px 0 4px;
}
.wrm-wk-detail .close {
  position: absolute; top: 10px; right: 12px;
  background: none; border: 0; font-size: 22px; line-height: 1;
  color: var(--ink-3); cursor: pointer; padding: 4px 8px;
}
.wrm-wk-detail .close:hover { color: var(--ink); }

.dl-top { display: flex; gap: 18px; flex-wrap: wrap; }
.dl-img {
  width: 200px; height: 130px; flex: none;
  background: var(--surface-2); border-radius: var(--r-soft); overflow: hidden;
}
.dl-img img { width: 100%; height: 100%; object-fit: cover; }
.dl-info { flex: 1; min-width: 240px; }
.dl-name { font-size: 19px; color: var(--ink); }
.dl-sub { font-size: 12px; color: var(--ink-3); margin: 3px 0 10px; }

.dl-tags { display: flex; gap: 7px; flex-wrap: wrap; margin-bottom: 10px; }
.dl-tags .tag {
  font-size: 11px; padding: 4px 11px;
  background: var(--surface-2); color: var(--ink-2);
  border-radius: var(--r-pill);
}
.dl-tags .tag.maint { background: var(--out-bg); color: var(--out-fg); }

.dl-desc { font-size: 13px; color: var(--ink-2); margin: 0 0 12px; }

.dl-book {
  display: inline-block;
  font-size: 13px; font-weight: 500;
  background: var(--clay); color: var(--on-clay);
  padding: 9px 20px; border-radius: var(--r-pill);
  text-decoration: none;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
}
.dl-book:hover, .dl-book:focus { background: var(--clay-press); color: var(--on-clay); text-decoration: none; }

.dl-avail { margin-top: 18px; border-top: 1px solid var(--line); padding-top: 14px; }
.dl-avail-head { font-size: 11px; letter-spacing: .08em; color: var(--ink-3); margin-bottom: 10px; }
.dl-days { display: grid; grid-template-columns: repeat(10, 1fr); gap: 5px; }
.dl-day { text-align: center; }
.dl-day .d { display: block; font-size: 9px; letter-spacing: .06em; color: var(--ink-3); }
.dl-day .n { display: block; font-size: 12px; color: var(--ink-2); margin-bottom: 4px; }
.dl-day .blk { display: block; height: 22px; border-radius: 3px; }
.dl-day .blk.free  { background: var(--free-bg); }
.dl-day .blk.taken { background: var(--held-bg); }
.dl-day .blk.maint { background: var(--out-bg); }

.dl-key { display: flex; gap: 16px; margin-top: 11px; font-size: 11px; color: var(--ink-3); }
.dl-key i { display: inline-block; width: 10px; height: 10px; border-radius: 2px; margin-right: 5px; }
.dl-key i.free  { background: var(--free-bg); }
.dl-key i.taken { background: var(--held-bg); }
.dl-key i.maint { background: var(--out-bg); }

.wrm-wk-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.wrm-wk-card {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--r-soft); overflow: hidden; cursor: pointer;
}
.wrm-wk-card:hover { border-color: var(--ink-3); }
.wrm-wk-card.sel { border-color: var(--clay); }
.wrm-wk-card.dim { opacity: .62; }
.wrm-wk-card .thumb { height: 62px; background: var(--surface-2); }
.wrm-wk-card .thumb img { width: 100%; height: 100%; object-fit: cover; }
.wrm-wk-card .body { padding: 12px 13px; }
.wrm-wk-card .nm { font-size: 14px; color: var(--ink); }
.wrm-wk-card .sub { font-size: 11px; color: var(--ink-3); margin: 2px 0 10px; }

.wrm-wk-card .strip { display: flex; gap: 4px; }
.wrm-wk-card .strip span { flex: 1; height: 20px; border-radius: 3px; }
.wrm-wk-card .strip span.free  { background: var(--free-bg); }
.wrm-wk-card .strip span.taken { background: var(--held-bg); }
.wrm-wk-card .strip span.maint { background: var(--out-bg); }

.wrm-wk-card .foot { margin-top: 11px; }
.wrm-wk-card .note { font-size: 11px; color: var(--out-fg); }
.wrm-wk-card .note.free { color: var(--free-fg); }

.wrm-wk-more { text-align: center; margin-top: 14px; }
.wrm-wk-more button {
  font-size: 13px; padding: 9px 22px;
  background: transparent; color: var(--ink-2);
  border: 1px solid var(--line); border-radius: var(--r-pill);
  cursor: pointer;
}
.wrm-wk-more button:hover { background: var(--surface-2); color: var(--ink); }

.wrm-wk-empty {
  text-align: center; padding: 38px 20px;
  background: var(--surface); border: 1px dashed var(--line);
  border-radius: var(--r-card); color: var(--ink-2);
}
.wrm-wk-empty h3 { margin: 0 0 6px; font-size: 17px; color: var(--ink); }
.wrm-wk-empty p { margin: 0; font-size: 13px; }

sp_widget.script:
(function() {

  var WEEKDAYS = ['SUN','MON','TUE','WED','THU','FRI','SAT'];
  var MONTHS   = ['JAN','FEB','MAR','APR','MAY','JUN',
                  'JUL','AUG','SEP','OCT','NOV','DEC'];

  // Reservation statuses that actually hold a workspace.
  var HOLDING = 'pending_check_in,checked_in';

  // --- 1. Work out the ten weekdays: this Monday to next Friday ---

  var todayYmd = new GlideDateTime().getDisplayValue().split(' ')[0];
  var tp = todayYmd.split('-');
  var todayUtc = Date.UTC(+tp[0], +tp[1] - 1, +tp[2]);

  // Step back to Monday. getUTCDay: 0 = Sunday.
  var dow = new Date(todayUtc).getUTCDay();
  var backToMonday = (dow === 0) ? 6 : (dow - 1);
  var mondayUtc = todayUtc - (backToMonday * 86400000);

  function ymd(ms) {
    var d = new Date(ms);
    var m = d.getUTCMonth() + 1;
    var day = d.getUTCDate();
    return d.getUTCFullYear() + '-' +
           (m < 10 ? '0' + m : m) + '-' +
           (day < 10 ? '0' + day : day);
  }

  var days = [];   // ten entries, index 0-4 this week, 5-9 next week
  for (var w = 0; w < 2; w++) {
    for (var i = 0; i < 5; i++) {
      var ms = mondayUtc + ((w * 7 + i) * 86400000);
      var d = new Date(ms);
      days.push({
        ymd:     ymd(ms),
        weekday: WEEKDAYS[d.getUTCDay()],
        dayNum:  ('0' + d.getUTCDate()).slice(-2),
        month:   MONTHS[d.getUTCMonth()],
        isToday: ymd(ms) === todayYmd,
        free:    0
      });
    }
  }

  var windowStart = days[0].ymd;
  var windowEnd   = days[9].ymd;

  // --- 2. Which workspaces are held on which days ---

  var held = {};   // { workspaceSysId: { 'YYYY-MM-DD': true } }

  var res = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  res.addQuery('reservation_status', 'IN', HOLDING);
  res.query();

  while (res.next()) {
    var wsId = res.getValue('workspace');
    if (!wsId) continue;

    var sDisp = res.getDisplayValue('work_start');
    var eDisp = res.getDisplayValue('work_end');
    if (!sDisp || !eDisp) continue;

    var sYmd = sDisp.split(' ')[0];
    var eYmd = eDisp.split(' ')[0];

    if (eYmd < windowStart || sYmd > windowEnd) continue;

    if (!held[wsId]) held[wsId] = {};

    var sParts = sYmd.split('-');
    var eParts = eYmd.split('-');
    var cur = Date.UTC(+sParts[0], +sParts[1] - 1, +sParts[2]);
    var end = Date.UTC(+eParts[0], +eParts[1] - 1, +eParts[2]);

    while (cur <= end) {
      held[wsId][ymd(cur)] = true;
      cur += 86400000;
    }
  }

  // --- 3. Build the workspace rows ---

  data.workspaces = [];
  var typeSet = {};

  var gr = new GlideRecord('x_1903615_worksp_0_workspace_options');
  // Decommissioned spaces shouldn't appear at all.
  gr.addQuery('status', '!=', 'decommissioned');
  gr.orderBy('workspace_name');
  gr.query();

  while (gr.next()) {
    var id      = gr.getUniqueValue();
    var status  = gr.getValue('status');
    var typeVal = gr.getValue('workspace_type');
    var typeLbl = gr.getDisplayValue('workspace_type');

    if (typeVal) typeSet[typeVal] = typeLbl;

    // Image: user_image fields hold an attachment reference.
    var raw = gr.getValue('image');
    var url = '';
    if (raw) {
      url = raw.indexOf('.') > -1
          ? (raw.charAt(0) === '/' ? raw : '/' + raw)
          : '/sys_attachment.do?sys_id=' + raw;
    }

    var dayStates = [];
    for (var k = 0; k < days.length; k++) {
      var state;
      if (status === 'under_maintenance') {
        state = 'maint';
      } else if (held[id] && held[id][days[k].ymd]) {
        state = 'taken';
      } else {
        state = 'free';
      }
      if (state === 'free') days[k].free++;
      dayStates.push(state);
    }

    data.workspaces.push({
      sysId:       id,
      name:        gr.getDisplayValue('workspace_name'),
      typeVal:     typeVal,
      typeLabel:   typeLbl,
      location:    gr.getDisplayValue('location'),
      capacity:    gr.getValue('max_occupancy'),
      description: gr.getValue('workspace_description'),
      imageUrl:    url,
      maint:       status === 'under_maintenance',
      days:        dayStates
    });
  }

  data.days = days;

  // --- 4. Filter pill options ---

  data.types = [];
  for (var t in typeSet) {
    data.types.push({ value: t, label: typeSet[t] });
  }
  data.types.sort(function(a, b) { return a.label < b.label ? -1 : 1; });

  // Catalog item to book against.
  data.bookUrl = '?id=sc_cat_item&sys_id=fe1e919e93c6c3108c8874dcebba10d0';

})();
